 'sin': lambda q,n,t,A: np.sin(q*t)*np.ones_like(A),
 'Aexp_t': lambda q,n,t,A: A**n*np.exp(-q*t),
 'expA': lambda q,n,t,A: np.exp(-q*A)*np.ones_like(t),
 'Aexp_A': lambda q,n,t,A: A**n*np.exp(-q*A),
 'texpA': lambda q,n,t,A: t*A**n*np.exp(-q*A),
 'Apow': lambda q,n,t,A: A**n*np.ones_like(t),
 'tpow': lambda q,n,t,A: t**n*np.ones_like(A)*np.exp(-q*t)
}
